"""Annie's Pub Tour - shared live Pint Tracker (single-file Streamlit app).

Every tap is written to one shared SQLite database on the server, and the
tracker refreshes itself every few seconds, so all five phones see the same
live league.

Run locally:   streamlit run app.py
Deploy:        Streamlit Community Cloud, entry point app.py
"""

from __future__ import annotations

import html
import sqlite3
import threading
from datetime import datetime
from pathlib import Path

import streamlit as st

TITLE = "Annie's Pub Tour"
SUBTITLE = "One day, Connemara to Clifden to The Quays - and every pint on the record"
REFRESH_SECONDS = 3
DB_PATH = Path(__file__).with_name("pub_tour.sqlite3")

LADS = (
    ("annie", "Annie", "One Cannie Annie", "#C7512F"),
    ("noel", "Noel", "The Reigning Champion", "#0E7490"),
    ("olly", "Olly", "The Gearbox Goblin of Guinness", "#B8791B"),
    ("jack", "Jack", "Eiffel Tower", "#1F6F63"),
    ("daniel", "Daniel", "The Tryline Terrorist", "#5B5BD6"),
)
NAMES = {key: name for key, name, _, _ in LADS}

BADGES = (
    (1, "🍺", "First Pint", "Broke the seal in Connemara."),
    (3, "🎩", "Hat Trick", "Three pints in the bag."),
    (10, "🔟", "Double Figures", "Ten pints across the day."),
    (15, "🌊", "Wild Atlantic Veteran", "Fifteen pints and still standing at the Crane."),
    (20, "👑", "Pub Legend", "Twenty pints. Songs will be written."),
    (25, "🦁", "Beer Baron", "Twenty-five pints. An empire of foam."),
)

HERO_IMAGE = "data:image/jpeg;base64,"

# --------------------------------------------------------------------------- #
# Shared storage (one database for every visitor)
# --------------------------------------------------------------------------- #
_LOCK = threading.Lock()


@st.cache_resource
def get_db() -> sqlite3.Connection:
    """Open the single shared connection used by every session."""
    conn = sqlite3.connect(DB_PATH, check_same_thread=False, isolation_level=None)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute(
        "CREATE TABLE IF NOT EXISTS pints ("
        " id INTEGER PRIMARY KEY AUTOINCREMENT, who TEXT NOT NULL, at TEXT NOT NULL)"
    )
    return conn


def add_pint(who: str) -> int:
    with _LOCK:
        db = get_db()
        db.execute("INSERT INTO pints(who, at) VALUES(?, ?)", (who, datetime.now().isoformat(timespec="seconds")))
        return db.execute("SELECT COUNT(*) FROM pints WHERE who = ?", (who,)).fetchone()[0]


def undo_for(who: str) -> None:
    with _LOCK:
        get_db().execute("DELETE FROM pints WHERE id = (SELECT MAX(id) FROM pints WHERE who = ?)", (who,))


def undo_last() -> None:
    with _LOCK:
        get_db().execute("DELETE FROM pints WHERE id = (SELECT MAX(id) FROM pints)")


def reset_league() -> None:
    with _LOCK:
        get_db().execute("DELETE FROM pints")


def snapshot() -> tuple[dict[str, int], list[sqlite3.Row]]:
    with _LOCK:
        db = get_db()
        totals = {key: 0 for key in NAMES}
        for row in db.execute("SELECT who, COUNT(*) AS n FROM pints GROUP BY who"):
            if row["who"] in totals:
                totals[row["who"]] = row["n"]
        recent = db.execute("SELECT who, at FROM pints ORDER BY id DESC LIMIT 20").fetchall()
    return totals, recent


def next_badge(n: int):
    return next((b for b in BADGES if n < b[0]), None)


def progress(n: int) -> float:
    nb = next_badge(n)
    if not nb:
        return 1.0
    prev = max([b[0] for b in BADGES if b[0] <= n], default=0)
    return (n - prev) / (nb[0] - prev)


# --------------------------------------------------------------------------- #
# Styling (same palette and glass design language as the HTML version)
# --------------------------------------------------------------------------- #
PALETTES = {
    "light": dict(bg="#FBF8F4", bg_alt="#F2ECE4", surface="rgba(255,255,255,.72)", border="rgba(26,22,20,.10)",
                  text="#1A1614", muted="#6B625C", primary="#C7512F", soft="rgba(199,81,47,.12)",
                  accent="#1F6F63", success="#1E7A54", shadow="0 18px 48px rgba(38,27,20,.12)"),
    "dark": dict(bg="#12100F", bg_alt="#1A1716", surface="rgba(38,34,32,.62)", border="rgba(255,246,238,.12)",
                 text="#F6F1EC", muted="#B3A79F", primary="#F0794F", soft="rgba(240,121,79,.16)",
                 accent="#4FD1B8", success="#3FBF87", shadow="0 20px 52px rgba(0,0,0,.46)"),
}


